<?php
/** GD Client Portal v3.5 — Client Files & Document Management 2.0. */
if (!defined('ABSPATH')) exit;

function gd_client_portal_documents_table(){ global $wpdb; return $wpdb->prefix.'gd_portal_documents'; }
function gd_client_portal_document_requests_table(){ global $wpdb; return $wpdb->prefix.'gd_portal_document_requests'; }
function gd_client_portal_documents_activate_tables(){
    global $wpdb; require_once ABSPATH.'wp-admin/includes/upgrade.php'; $c=$wpdb->get_charset_collate();
    $t=gd_client_portal_documents_table();
    dbDelta("CREATE TABLE $t (id bigint(20) unsigned NOT NULL AUTO_INCREMENT,tenant_id bigint(20) unsigned NOT NULL DEFAULT 0,user_id bigint(20) unsigned NOT NULL DEFAULT 0,project_id bigint(20) unsigned NOT NULL DEFAULT 0,contract_id bigint(20) unsigned NOT NULL DEFAULT 0,parent_id bigint(20) unsigned NOT NULL DEFAULT 0,folder varchar(190) NOT NULL DEFAULT '',title varchar(255) NOT NULL,file_name varchar(255) NOT NULL,file_path text NOT NULL,file_url text NULL,mime_type varchar(120) NOT NULL,filesize bigint(20) unsigned NOT NULL DEFAULT 0,version int(10) unsigned NOT NULL DEFAULT 1,status varchar(30) NOT NULL DEFAULT 'active',expires_at date NULL,uploaded_by bigint(20) unsigned NOT NULL DEFAULT 0,created_at datetime DEFAULT CURRENT_TIMESTAMP,updated_at datetime DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(id),KEY tenant_id(tenant_id),KEY user_id(user_id),KEY project_id(project_id),KEY contract_id(contract_id),KEY parent_id(parent_id),KEY status(status),KEY folder(folder)) $c;");
    $r=gd_client_portal_document_requests_table();
    dbDelta("CREATE TABLE $r (id bigint(20) unsigned NOT NULL AUTO_INCREMENT,tenant_id bigint(20) unsigned NOT NULL DEFAULT 0,user_id bigint(20) unsigned NOT NULL DEFAULT 0,project_id bigint(20) unsigned NOT NULL DEFAULT 0,title varchar(255) NOT NULL,description text NULL,folder varchar(190) NOT NULL DEFAULT '',status varchar(30) NOT NULL DEFAULT 'open',due_date date NULL,created_by bigint(20) unsigned NOT NULL DEFAULT 0,fulfilled_document_id bigint(20) unsigned NOT NULL DEFAULT 0,created_at datetime DEFAULT CURRENT_TIMESTAMP,updated_at datetime DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(id),KEY tenant_id(tenant_id),KEY user_id(user_id),KEY project_id(project_id),KEY status(status)) $c;");
}
function gd_client_portal_documents_upgrade(){ if(absint(get_option('gd_client_portal_documents_schema_version',0))<1){gd_client_portal_documents_activate_tables();update_option('gd_client_portal_documents_schema_version',1);} }
// Schema lifecycle is managed centrally by GDCP_Migration_Manager (v6.8+).

function gd_client_portal_document_allowed_mimes(){return array('pdf'=>'application/pdf','doc'=>'application/msword','docx'=>'application/vnd.openxmlformats-officedocument.wordprocessingml.document','xls'=>'application/vnd.ms-excel','xlsx'=>'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet','ppt'=>'application/vnd.ms-powerpoint','pptx'=>'application/vnd.openxmlformats-officedocument.presentationml.presentation','txt'=>'text/plain','csv'=>'text/csv','jpg'=>'image/jpeg','jpeg'=>'image/jpeg','png'=>'image/png','webp'=>'image/webp','zip'=>'application/zip');}
function gd_client_portal_document_access($row,$write=false){
    if(!$row || !is_user_logged_in() || !gd_client_portal_verify_request()) return false;
    if(gd_client_portal_is_platform_admin()) return true;
    $tenant=absint(gd_client_portal_get_current_tenant_id()); if(!$tenant || absint($row->tenant_id)!==$tenant)return false;
    if(gd_client_portal_user_is_tenant_admin()) return true;
    if(absint($row->user_id)===gd_client_portal_cached_current_user_id())return true;
    if(absint($row->project_id)){ $p=gd_client_portal_get_project_by_id($row->project_id); if($p && gd_client_portal_verify_project_access($p))return true; }
    return false;
}
function gd_client_portal_documents_get($args=array()){ return gdcp_document_repository()->list($args); }
function gd_client_portal_document_by_id($id){ return gdcp_document_repository()->find($id); }
function gd_client_portal_document_notify($user,$title,$body,$project=0,$tenant=0){if(function_exists('gd_client_portal_create_notification')&&$user)gd_client_portal_create_notification(absint($user),$title,$body,'document',absint($project),absint($tenant));}
function gd_client_portal_document_audit($event,$summary,$row,$extra=array()){if(function_exists('gd_client_portal_audit_log'))gd_client_portal_audit_log($event,$summary,absint($row->project_id),absint($row->tenant_id),$row->file_name,'document',absint($row->id),$extra);}

function gd_client_portal_document_upload_ajax(){
    gd_client_portal_ajax_guard('gd_client_portal_documents','nonce'); global $wpdb;
    $project_id=absint($_POST['project_id']??0);$contract_id=absint($_POST['contract_id']??0);$folder=sanitize_text_field(wp_unslash($_POST['folder']??''));$title=sanitize_text_field(wp_unslash($_POST['title']??''));$expires=sanitize_text_field(wp_unslash($_POST['expires_at']??''));$user_id=gd_client_portal_cached_current_user_id();
    $project=$project_id?gd_client_portal_get_project_by_id($project_id):false;
    if($project && !gd_client_portal_verify_project_access($project,true))wp_send_json_error(array('message'=>'Project access denied.'),403);
    if($contract_id){$contract=function_exists('gd_client_portal_contract_by_id')?gd_client_portal_contract_by_id($contract_id):false;if(!$contract)wp_send_json_error(array('message'=>'Contract not found.'),404);if($project_id && (absint($contract->project_id)!==$project_id || absint($contract->tenant_id)!==absint($project->tenant_id) || absint($contract->user_id)!==absint($project->user_id)))wp_send_json_error(array('message'=>'Contract does not match project/client.'),403);if(!$project_id && !gd_client_portal_is_platform_admin() && !gd_client_portal_user_is_tenant_admin() && absint($contract->tenant_id)!==absint(gd_client_portal_get_current_tenant_id()))wp_send_json_error(array('message'=>'Contract access denied.'),403);}
    if(!$project && !gd_client_portal_is_platform_admin() && !gd_client_portal_user_is_tenant_admin())$project_id=0;
    if(!empty($_FILES['document_file']['error']))wp_send_json_error(array('message'=>'Please select a valid file.'));
    $file=$_FILES['document_file'];$allowed=gd_client_portal_document_allowed_mimes();$max_size=apply_filters('gd_client_portal_document_max_upload_size',10*MB_IN_BYTES);if(absint($file['size'])<=0||absint($file['size'])>$max_size)wp_send_json_error(array('message'=>'The selected file exceeds the allowed upload size.'));$ext=strtolower(pathinfo($file['name'],PATHINFO_EXTENSION));if(!isset($allowed[$ext]))wp_send_json_error(array('message'=>'This file type is not allowed.'));$checked=wp_check_filetype_and_ext($file['tmp_name'],$file['name'],$allowed);if(empty($checked['ext'])||empty($checked['type'])||$checked['ext']!==$ext)wp_send_json_error(array('message'=>'The uploaded file failed type validation.'));
    require_once ABSPATH.'wp-admin/includes/file.php'; $upload=wp_handle_upload($file,array('test_form'=>false,'mimes'=>$allowed));if(!empty($upload['error']))wp_send_json_error(array('message'=>$upload['error']));
    $tenant=$project?absint($project->tenant_id):absint(gd_client_portal_get_current_tenant_id()); if(!$tenant && gd_client_portal_is_platform_admin())$tenant=0;
    $owner=$project?absint($project->user_id):$user_id;$row=gdcp_document_service()->upload(array('tenant_id'=>$tenant,'user_id'=>$owner,'project_id'=>$project_id,'contract_id'=>$contract_id,'folder'=>$folder,'title'=>$title?:sanitize_text_field(pathinfo($file['name'],PATHINFO_FILENAME)),'file_name'=>$file['name'],'file_path'=>$upload['file'],'file_url'=>$upload['url'],'mime_type'=>$upload['type'],'filesize'=>absint($file['size']),'status'=>'active','expires_at'=>preg_match('/^\d{4}-\d{2}-\d{2}$/',$expires)?$expires:null,'uploaded_by'=>$user_id,'created_at'=>current_time('mysql'),'updated_at'=>current_time('mysql')));
    if(is_wp_error($row))wp_send_json_error(array('message'=>$row->get_error_message()));$version=absint($row->version);gd_client_portal_document_audit('document_uploaded',sprintf(__('Document uploaded: %s','gd-client-portal'),$row->file_name),$row,array('version'=>$version,'folder'=>$folder));if($owner!==$user_id)gd_client_portal_document_notify($owner,__('New document uploaded','gd-client-portal'),sprintf(__('A new document is available: %s','gd-client-portal'),$row->title),$project_id,$tenant);wp_send_json_success(array('message'=>sprintf(__('Document uploaded (v%d).','gd-client-portal'),$version),'document_id'=>$row->id));
}
add_action('wp_ajax_gd_client_portal_document_upload','gd_client_portal_document_upload_ajax');

function gd_client_portal_document_status_ajax(){
    gd_client_portal_ajax_guard('gd_client_portal_documents','nonce');$id=absint($_POST['document_id']??0);$row=gd_client_portal_document_by_id($id);if(!$row||!gd_client_portal_document_access($row,true))wp_send_json_error(array('message'=>'Access denied.'),403);$status=sanitize_key($_POST['status']??'active');$row=gdcp_document_service()->change_status($id,$status);if(is_wp_error($row))wp_send_json_error(array('message'=>$row->get_error_message()),400);gd_client_portal_document_audit('document_status_changed',sprintf(__('Document status changed: %s','gd-client-portal'),$status),$row,array('status'=>$status));wp_send_json_success(array('message'=>__('Document updated.','gd-client-portal')));
}
add_action('wp_ajax_gd_client_portal_document_status','gd_client_portal_document_status_ajax');

function gd_client_portal_document_delete_ajax(){
    gd_client_portal_ajax_guard('gd_client_portal_documents','nonce');$row=gd_client_portal_document_by_id(absint($_POST['document_id']??0));if(!$row||!gd_client_portal_document_access($row,true))wp_send_json_error(array('message'=>'Access denied.'),403);if($row->file_path&&file_exists($row->file_path))@unlink($row->file_path);$deleted=gdcp_document_service()->delete($row->id);if(is_wp_error($deleted))wp_send_json_error(array('message'=>$deleted->get_error_message()),400);gd_client_portal_document_audit('document_deleted',sprintf(__('Document deleted: %s','gd-client-portal'),$row->file_name),$row);wp_send_json_success(array('message'=>__('Document deleted.','gd-client-portal')));
}
