function gd_client_portal_document_download(){ $id=absint($_GET['document_id']??0); $nonce=isset($_GET['_wpnonce'])?sanitize_text_field(wp_unslash($_GET['_wpnonce'])):''; if(!$id || !wp_verify_nonce($nonce,'gd_client_portal_document_download_'.$id)) wp_die(esc_html__('Invalid download request.','gd-client-portal'),'',array('response'=>403)); if(!is_user_logged_in())wp_die(esc_html__('Please sign in.','gd-client-portal'),'',array('response'=>403));$row=gd_client_portal_document_by_id($id);if(!$row||!gd_client_portal_document_access($row))wp_die(esc_html__('You do not have access to this document.','gd-client-portal'),'',array('response'=>403));if($row->status==='archived'||$row->status==='rejected')wp_die(esc_html__('This document is no longer available.','gd-client-portal'),'',array('response'=>410));if($row->expires_at&&strtotime($row->expires_at.' 23:59:59')<current_time('timestamp'))wp_die(esc_html__('This document has expired.','gd-client-portal'),'',array('response'=>410));if(!gd_client_portal_verify_upload_path($row->file_path))wp_die(esc_html__('File unavailable.','gd-client-portal'),'',array('response'=>404));$safe_path=realpath($row->file_path);nocache_headers();header('X-Content-Type-Options: nosniff');header('Content-Type: '.($row->mime_type?:'application/octet-stream'));header('Content-Length: '.filesize($safe_path));header('Content-Disposition: attachment; filename="'.sanitize_file_name($row->file_name).'"');readfile($safe_path);exit;}
add_action('admin_post_gd_client_portal_document_download','gd_client_portal_document_download');

function gd_client_portal_document_requests_ajax(){
    gd_client_portal_ajax_guard('gd_client_portal_documents','nonce');$action=sanitize_key($_POST['request_action']??'create');$id=absint($_POST['request_id']??0);
    if($action==='create'){$project_id=absint($_POST['project_id']??0);$p=$project_id?gd_client_portal_get_project_by_id($project_id):false;if(!$p||!gd_client_portal_verify_project_access($p,true))wp_send_json_error(array('message'=>'Project access denied.'),403);if(!(gd_client_portal_is_platform_admin()||gd_client_portal_user_is_tenant_admin()))wp_send_json_error(array('message'=>'Admin access required.'));$title=sanitize_text_field(wp_unslash($_POST['title']??''));if(!$title)wp_send_json_error(array('message'=>'Request title is required.'));$r=gdcp_document_service()->create_request(array('tenant_id'=>absint($p->tenant_id),'user_id'=>absint($p->user_id),'project_id'=>$project_id,'title'=>$title,'description'=>sanitize_textarea_field(wp_unslash($_POST['description']??'')),'folder'=>sanitize_text_field(wp_unslash($_POST['folder']??'')),'status'=>'open','due_date'=>sanitize_text_field($_POST['due_date']??'')?:null,'created_by'=>gd_client_portal_cached_current_user_id(),'created_at'=>current_time('mysql'),'updated_at'=>current_time('mysql')));if(is_wp_error($r))wp_send_json_error(array('message'=>$r->get_error_message()),400);gd_client_portal_document_notify($p->user_id,__('Document requested','gd-client-portal'),sprintf(__('Please provide: %s','gd-client-portal'),$title),$project_id,$p->tenant_id);wp_send_json_success(array('message'=>__('Document request sent.','gd-client-portal')));}
    if($action==='close'){$r=gdcp_document_repository()->find_request($id);if(!$r||!(gd_client_portal_is_platform_admin()||gd_client_portal_user_is_tenant_admin())||!gd_client_portal_verify_tenant_access($r->tenant_id))wp_send_json_error(array('message'=>'Access denied.'),403);$result=gdcp_document_service()->fulfill_request($id,0);if(is_wp_error($result))wp_send_json_error(array('message'=>$result->get_error_message()),400);wp_send_json_success(array('message'=>__('Request closed.','gd-client-portal')));}
    wp_send_json_error(array('message'=>'Invalid request.'));
}
add_action('wp_ajax_gd_client_portal_document_request','gd_client_portal_document_requests_ajax');

function gd_client_portal_render_documents($atts=array()){
    if(!is_user_logged_in()||!gd_client_portal_verify_request())return gd_client_portal_render_access_gate(__('Document Center','gd-client-portal'),__('Please sign in to access your files.','gd-client-portal'));
    $atts=shortcode_atts(array('project_id'=>0),$atts);$project_id=absint($atts['project_id']?:($_GET['project_id']??0));if($project_id){$p=gd_client_portal_get_project_by_id($project_id);if(!$p||!gd_client_portal_verify_project_access($p))return gd_client_portal_render_access_gate(__('Document Center','gd-client-portal'),__('You do not have access to this project.','gd-client-portal'));}
    $docs=gd_client_portal_documents_get(array('project_id'=>$project_id,'limit'=>300));$nonce=wp_create_nonce('gd_client_portal_documents');ob_start();wp_enqueue_style('gd-client-portal-documents');wp_enqueue_script('gd-client-portal-documents');
    echo '<div class="gd-doc-center"><header class="gd-doc-hero"><div><span>GD CLIENT PORTAL · V3.5</span><h2>'.esc_html__('Client Files & Documents','gd-client-portal').'</h2><p>'.esc_html__('Organize project files, versions, approvals and document requests in one secure workspace.','gd-client-portal').'</p></div><strong>'.count($docs).' '.esc_html__('documents','gd-client-portal').'</strong></header>';
    echo '<form class="gd-doc-upload" enctype="multipart/form-data"><input type="hidden" name="project_id" value="'.intval($project_id).'"/><input type="hidden" name="nonce" value="'.esc_attr($nonce).'"/><input name="title" placeholder="'.esc_attr__('Document title','gd-client-portal').'"/><input name="folder" placeholder="'.esc_attr__('Folder (e.g. Briefs / Brand)','gd-client-portal').'"/><input name="expires_at" type="date" title="'.esc_attr__('Expiry date','gd-client-portal').'"/><input type="file" name="document_file" required/><button type="submit">'.esc_html__('Upload document','gd-client-portal').'</button><span class="gd-doc-status" aria-live="polite"></span></form>';
    $folders=array();foreach($docs as $d)$folders[$d->folder][]=$d; if(!$docs)echo '<div class="gd-doc-empty"><strong>'.esc_html__('No documents yet.','gd-client-portal').'</strong><p>'.esc_html__('Uploaded files and requested documents will appear here.','gd-client-portal').'</p></div>';
    foreach($folders as $folder=>$items){echo '<section class="gd-doc-folder"><div class="gd-doc-folder-head"><h3>📁 '.esc_html($folder?:__('General','gd-client-portal')).'</h3><span>'.count($items).'</span></div><div class="gd-doc-grid">';foreach($items as $d){$download=wp_nonce_url(admin_url('admin-post.php?action=gd_client_portal_document_download&document_id='.absint($d->id)),'gd_client_portal_document_download_'.$d->id);$expired=$d->expires_at&&strtotime($d->expires_at.' 23:59:59')<current_time('timestamp');echo '<article class="gd-doc-card '.($expired?'is-expired':'').'"><div class="gd-doc-icon">'.esc_html(strtoupper(pathinfo($d->file_name,PATHINFO_EXTENSION))).'</div><div class="gd-doc-main"><h4>'.esc_html($d->title).'</h4><p>'.esc_html($d->file_name).' · v'.intval($d->version).' · '.size_format($d->filesize).'</p><div class="gd-doc-meta"><span>'.esc_html(ucfirst($d->status)).'</span>'.($d->expires_at?'<span>'.esc_html__('Expires','gd-client-portal').' '.esc_html($d->expires_at).'</span>':'').'</div></div><a class="gd-doc-button" href="'.esc_url($download).'">'.esc_html__('Download','gd-client-portal').'</a></article>'; }echo '</div></section>';}
    $reqs=array(); if($project_id){$reqs=gdcp_document_repository()->list_requests(array('project_id'=>$project_id,'user_id'=>gd_client_portal_cached_current_user_id(),'status'=>'open'));} if($reqs){echo '<section class=\"gd-doc-requests\"><h3>'.esc_html__('Documents requested from you','gd-client-portal').'</h3>';foreach($reqs as $r)echo '<div class=\"gd-doc-request\"><strong>'.esc_html($r->title).'</strong><span>'.esc_html($r->description).'</span>'.($r->due_date?'<small>'.esc_html__('Due','gd-client-portal').' '.esc_html($r->due_date).'</small>':'').'</div>';echo '</section>';} echo '</div>';return ob_get_clean();
}
add_shortcode('gd_documents','gd_client_portal_render_documents');add_shortcode('gd_file_center','gd_client_portal_render_documents');add_shortcode('gd_client_files','gd_client_portal_render_documents');
function gd_client_portal_documents_dashboard(){return gd_client_portal_render_documents(array());} add_action('init',function(){if(function_exists('gd_client_portal_register_dashboard_view'))gd_client_portal_register_dashboard_view('files','gd_client_portal_documents_dashboard');});
function gd_client_portal_documents_admin_menu(){add_submenu_page('gd-client-portal',__('Client Files & Documents','gd-client-portal'),__('Files & Documents','gd-client-portal'),'gd_client_portal_access_admin','gd-client-portal-documents','gd_client_portal_documents_admin_page');} add_action('admin_menu','gd_client_portal_documents_admin_menu',20);
function gd_client_portal_documents_admin_page(){if(!gd_client_portal_user_can_access_admin())wp_die(esc_html__('You do not have permission to access this page.','gd-client-portal'));$docs=gd_client_portal_documents_get(array('limit'=>500));echo '<div class="wrap gd-doc-admin"><h1>'.esc_html__('Client Files & Documents','gd-client-portal').'</h1><p>'.esc_html__('Manage document versions, statuses and tenant-scoped files.','gd-client-portal').'</p><table class="widefat striped"><thead><tr><th>ID</th><th>Document</th><th>Project</th><th>Tenant</th><th>Version</th><th>Status</th><th>Expiry</th><th>Uploaded</th></tr></thead><tbody>';if(!$docs)echo '<tr><td colspan="8">'.esc_html__('No documents found.','gd-client-portal').'</td></tr>';foreach($docs as $d){$p=$d->project_id?gd_client_portal_get_project_by_id($d->project_id):false;$u=gd_client_portal_cached_user($d->uploaded_by);echo '<tr><td>'.intval($d->id).'</td><td><strong>'.esc_html($d->title).'</strong><br><small>'.esc_html($d->file_name).'</small></td><td>'.($p?'#'.intval($p->id).' '.esc_html($p->title):'—').'</td><td>'.intval($d->tenant_id).'</td><td>v'.intval($d->version).'</td><td>'.esc_html(ucfirst($d->status)).'</td><td>'.esc_html($d->expires_at?:'—').'</td><td>'.esc_html($u?$u->display_name:'—').'</td></tr>';}echo '</tbody></table></div>';}
function gd_client_portal_documents_assets(){wp_register_style('gd-client-portal-documents',GD_CLIENT_PORTAL_URL.'assets/documents.css',array('gd-client-portal'),GD_CLIENT_PORTAL_VERSION);wp_register_script('gd-client-portal-documents',GD_CLIENT_PORTAL_URL.'assets/documents.js',array('jquery'),GD_CLIENT_PORTAL_VERSION,true);wp_localize_script('gd-client-portal-documents','GDCPDocuments',array('ajax_url'=>admin_url('admin-ajax.php'),'nonce'=>wp_create_nonce('gd_client_portal_documents'),'action'=>'gd_client_portal_document_upload'));}add_action('wp_enqueue_scripts','gd_client_portal_documents_assets');add_action('admin_enqueue_scripts','gd_client_portal_documents_assets');
